update public.rc_articles
set body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A query is a public listening initiative: up to five ordered questions, published as its own page or embedded in a Grove article, with the answers coming back to you here."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create a query"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From the query list, select "},{"type":"text","text":"New query","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in an internal title (for your own list), a public title (what a listener sees), and a public introduction saying why you''re asking and what you''ll do with the answers. Select "},{"type":"text","text":"Create query","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You land on the new query''s Questions tab."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add questions"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in a question''s prompt, and optionally public guidance, internal context (staff-only), a maximum answer length, and whether it''s required."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Add question","marks":[{"type":"bold"}]},{"type":"text","text":". Repeat for up to five questions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reorder or duplicate a question with the buttons on its card, or remove one — before anyone has answered."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Configure settings"}]},{"type":"paragraph","content":[{"type":"text","text":"The Settings tab covers everything about how the query behaves, separate from its questions:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Participant information","marks":[{"type":"bold"}]},{"type":"text","text":" — which details (name, city, email, phone, a free-text note) to ask for, each set to don''t ask, optional, or required. Asked once for the whole submission, never per question."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Consent and attribution","marks":[{"type":"bold"}]},{"type":"text","text":" — three separate questions that stay separate on the record: permission to be contacted, permission to be named, and the option to request anonymity. Permission to be contacted is not permission to be named, and asking for anonymity is neither. The consent terms text itself is required and is recorded with the submission at the moment it''s accepted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Opens and closes dates","marks":[{"type":"bold"}]},{"type":"text","text":" — both optional; leaving them blank means the query opens as soon as you select "},{"type":"text","text":"Open for responses","marks":[{"type":"bold"}]},{"type":"text","text":" and stays open until you close it. Someone already recording when a close date passes may still finish and submit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Transcription","marks":[{"type":"bold"}]},{"type":"text","text":" — manual (send answers after reviewing them) or automatic (every answer is queued the moment it''s submitted, then sent in one click from the Submissions tab)."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish it"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the query''s header — visible from any tab — select "},{"type":"text","text":"Open for responses","marks":[{"type":"bold"}]},{"type":"text","text":". Until then, the public link and embed code don''t work, even for someone who already has them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go to the Share tab for a "},{"type":"text","text":"Copy link","marks":[{"type":"bold"}]},{"type":"text","text":" button for the standalone public page, and a "},{"type":"text","text":"Copy embed code","marks":[{"type":"bold"}]},{"type":"text","text":" button for a ready-made Grove iframe snippet — paste it into a Grove Responsive Embed element unchanged. If you add or remove questions later, copy the embed code again."}]}]}]},{"type":"figure","attrs":{"mediaId":"75a53aef-70d8-4f39-879d-d04253d87bff","alt":"A query''s Share tab, with the Public link and Grove embed code cards and their Copy buttons.","caption":"The Share tab, once a query is ready to publish."}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Preview","marks":[{"type":"bold"}]},{"type":"text","text":" (always available, even on a draft) to walk through the query as a participant would — nothing is submitted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once a query has submissions, question wording stays editable, but removing or reordering questions is no longer offered — an answer keeps the exact wording it was asked under."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The header''s action changes with status: open queries offer "},{"type":"text","text":"Close query","marks":[{"type":"bold"}]},{"type":"text","text":" (stops new responses; anyone already recording can still finish); closed ones offer "},{"type":"text","text":"Open for responses","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Archive query","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A query can be deleted only before it has any submissions, from the Settings tab. Once a submission exists, archiving — which keeps every response, answer, and transcription link — is how you finish with it."}]}]}]}]}'::jsonb,
    source = 'editor'::public.rc_source,
    version_note = 'Added the Share tab screenshot'
where slug = 'audience-listening-create-and-publish' and not edited_since_release;

update public.rc_articles
set body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The content library holds everything a rundown can pull from — news, promos, membership messages, PSAs, legal IDs, and more. Any tool member can add to it, not just producers."}]},{"type":"figure","attrs":{"mediaId":"9a827740-7123-435b-8f72-13ec4c1d35bb","alt":"The content library list, with its content-type/status filters and Import from DAD / + New content item buttons above it.","caption":"The content library."}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add a content item"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the library, optionally filter by content type or approval status, then select "},{"type":"text","text":"+ New content item","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in a title, content type, summary, script, expected duration, and effective dates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Create content item","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add its components"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the item''s page, expand "},{"type":"text","text":"Add a component","marks":[{"type":"bold"}]},{"type":"text","text":" — choose a type (live intro, recorded audio, live outro, or an optional tag), a sequence, a duration, and a script. Select "},{"type":"text","text":"Add component","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A required component counts toward the item''s total time; an optional one doesn''t."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Approve it"}]},{"type":"paragraph","content":[{"type":"text","text":"An item starts as a draft. Set its status to Approved, in the Status panel on its page, before it can be picked for a rundown — only approved items are offered when filling a break."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Import WUWF''s DAD cut library"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From the library, open the import screen and upload the Standard Library export from DAD (Library screen → Generate Reports → Standard Library) — optionally with its companion Groups report."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Preview import","marks":[{"type":"bold"}]},{"type":"text","text":" to see the plan: new items, updates to existing ones, and anything it couldn''t place."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Import","marks":[{"type":"bold"}]},{"type":"text","text":" to confirm."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"There''s no audio upload here. WUWF''s playback system (ENCO/DAD) is where recorded material actually plays from — a content item is metadata and a script, not an audio file."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-running the import later updates an already-imported item in place (matched by its DAD cart number) instead of creating a duplicate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retiring stale content is an ordinary status change, not a delete — nothing in the library is ever removed outright."}]}]}]}]}'::jsonb,
    source = 'editor'::public.rc_source,
    version_note = 'Added the content library screenshot'
where slug = 'log-content-library' and not edited_since_release;

update public.rc_articles
set body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A contract''s setup is five steps end to end, taking a signed order from a blank form to something that can actually be scheduled."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Order"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select the underwriter, enter the order number, the sponsorship total, the campaign''s run dates, a sponsorship category, and an account rep, with optional notes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Continue to schedule","marks":[{"type":"bold"}]},{"type":"text","text":" — or, instead of typing everything by hand, upload the signed agreement under “Or start from the signed agreement” and select "},{"type":"text","text":"Create from the agreement","marks":[{"type":"bold"}]},{"type":"text","text":" to have it read from the document. What you''ve already typed always wins over its reading."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Schedule"}]},{"type":"paragraph","content":[{"type":"text","text":"Add each line from the order — pool or program, days, dates, spot count, and the rest — through the schedule line editor, one at a time. Select "},{"type":"text","text":"Continue to copy","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Copy"}]},{"type":"paragraph","content":[{"type":"text","text":"Link or create the underwriting messages this contract will run, on the Copy step — the same panel the contract''s own Copy tab uses later. Select "},{"type":"text","text":"Continue to traffic policy","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Traffic policy"}]},{"type":"paragraph","content":[{"type":"text","text":"Set the total spots on the order, the preemption/makegood policy, whether an affidavit is required, whether makegoods need agency approval, and separation. Select "},{"type":"text","text":"Save policy","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"Continue to review","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review and activate"}]},{"type":"paragraph","content":[{"type":"text","text":"The contract page shows a “Ready to activate?” checklist against the order, agreement, schedule, copy, and policy, each with a fix-it link if something''s missing. Select "},{"type":"text","text":"Activate contract","marks":[{"type":"bold"}]},{"type":"text","text":" once it''s clear."}]},{"type":"figure","attrs":{"mediaId":"63d5662b-5dac-45dc-9d29-e21796a563f5","alt":"A draft contract''s \"Ready to activate?\" checklist, showing which of the order, agreement, schedule, copy, and policy steps are complete.","caption":"The readiness checklist on a draft contract."}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing schedules until activation — a draft contract can be edited freely, and can be deleted outright if it turns out not to be needed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"“Create from the agreement” reads a scanned or photographed signed order with one model call; it never invents a sponsor, program, or pool that isn''t already on file — an unrecognized name is refused, not guessed."}]}]}]}]}'::jsonb,
    source = 'editor'::public.rc_source,
    version_note = 'Added the readiness checklist screenshot'
where slug = 'underwriting-set-up-a-contract' and not edited_since_release;

